using System;
using KardashevAscent.Simulation.Solar;
using NUnit.Framework;

namespace KardashevAscent.Simulation.Tests.Solar
{
    /// <summary>
    /// Solar model (design doc steps 1–9) checked against pvlib.
    /// Reference values: PvlibReference.cs, regenerated by prototypes/solar/compare_pvlib.py.
    /// </summary>
    public class SolarModelTests
    {
        const double Deg = SolarConstants.DegToRad;

        // Step 1: orbit

        [Test]
        public void Kepler_CircularOrbit_EccentricAnomalyEqualsMeanAnomaly()
        {
            Assert.AreEqual(1.234, Orbit.SolveKepler(1.234, 0.0), 1e-15);
        }

        [TestCase(0.3, 0.9)]
        [TestCase(2.5, 0.5)]
        [TestCase(5.9, 0.0167)]
        public void Kepler_SolvesEquation(double meanAnomaly, double e)
        {
            double E = Orbit.SolveKepler(meanAnomaly, e);
            Assert.AreEqual(meanAnomaly, E - e * Math.Sin(E), 1e-12);
        }

        [Test]
        public void ExtraterrestrialIrradiance_EarthIsSolarConstant()
        {
            double g0 = Orbit.ExtraterrestrialIrradiance(SolarConstants.SolarLuminosity, SolarConstants.AstronomicalUnit);
            Assert.AreEqual(1361.0, g0, 1.0);
        }

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.EarthOrbit))]
        public void EarthOrbit_DistanceAndDeclinationMatchSpa(double[] row)
        {
            double n = row[0];
            double meanAnomaly = (357.5291 + 0.98560028 * n) % 360.0 * Deg;
            double perihelionLongitude = (282.9372 + 4.70935e-5 * n) * Deg;
            const double e = 0.0167;

            double nu = Orbit.TrueAnomaly(Orbit.SolveKepler(meanAnomaly, e), e);
            Assert.AreEqual(row[1], Orbit.Distance(1.0, e, nu), 2e-4, "distance (AU)");
            double declination = SunPosition.Declination(23.44 * Deg, nu + perihelionLongitude);
            Assert.AreEqual(row[2], declination / Deg, 0.02, "declination (deg)");
        }

        // Steps 2–3: sun on the sky

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.SunPosition))]
        public void SunPosition_MatchesPvlib(double[] row)
        {
            Double3 sun = SunPosition.Direction(row[0] * Deg, row[1] * Deg, row[2] * Deg);
            Assert.AreEqual(row[3], SunPosition.ZenithDegrees(sun), 1e-9, "zenith");
            Assert.AreEqual(row[4], SunPosition.AzimuthDegrees(sun), 1e-9, "azimuth");
        }

        [TestCase(-30.0, 0.0, 30.0, 0.0, TestName = "Noon, southern hemisphere: sun due north")]
        [TestCase(45.0, -23.44, 68.44, 180.0, TestName = "Noon, northern winter: sun due south")]
        [TestCase(10.0, 23.44, 13.44, 0.0, TestName = "Noon, tropics in June: sun north of zenith")]
        public void SunPosition_AtNoon(double latitude, double declination, double zenith, double azimuth)
        {
            Double3 sun = SunPosition.Direction(latitude * Deg, declination * Deg, 0.0);
            Assert.AreEqual(zenith, SunPosition.ZenithDegrees(sun), 1e-9);
            Assert.AreEqual(azimuth, SunPosition.AzimuthDegrees(sun), 1e-9);
        }

        [Test]
        public void SunPosition_Midnight_IsBelowHorizon()
        {
            double h = SunPosition.HourAngle(0.0, 24.0);
            Assert.AreEqual(-Math.PI, h, 1e-15);
            Assert.Less(SunPosition.Direction(0.0, 0.0, h).Up, 0.0);
        }

        // Steps 4–7: panel

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.Incidence))]
        public void CosIncidence_MatchesPvlib(double[] row)
        {
            Double3 normal = PanelModel.Normal(row[0] * Deg, row[1] * Deg);
            Assert.AreEqual(row[4], PanelModel.CosIncidence(normal, SunFrom(row[2], row[3])), 1e-12);
        }

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.AirMass))]
        public void AirMass_MatchesPvlib(double[] row)
        {
            Assert.AreEqual(row[1], Atmosphere.AirMassKastenYoung(row[0]), 1e-9);
        }

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.PlaneOfArray))]
        public void PlaneOfArray_MatchesPvlibIsotropic(double[] row)
        {
            double tilt = row[0] * Deg;
            double cosTheta = PanelModel.CosIncidence(PanelModel.Normal(tilt, row[1] * Deg), SunFrom(row[2], row[3]));
            double poa = PanelModel.PlaneOfArray(row[4], row[6], row[5], cosTheta, tilt, row[7]);
            Assert.AreEqual(row[8], poa, 1e-9);
        }

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.CellTemperature))]
        public void CellTemperature_MatchesPvlibRoss(double[] row)
        {
            Assert.AreEqual(row[3], PanelModel.CellTemperature(row[0], row[1], row[2]), 1e-9);
        }

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.PanelPower))]
        public void Power_MatchesPvlibPvwatts(double[] row)
        {
            Assert.AreEqual(row[4], PanelModel.Power(row[0], row[2], row[3], row[1]), 1e-9);
        }

        [Test]
        public void Power_DustAndSpectrumScaleOutput()
        {
            double clean = PanelModel.Power(1000.0, 1.0, 0.2, 25.0);
            Assert.AreEqual(200.0, clean, 1e-12);
            Assert.AreEqual(200.0 * 0.9 * 0.75, PanelModel.Power(1000.0, 1.0, 0.2, 25.0, fSpec: 0.9, fDust: 0.25), 1e-12);
        }

        // Steps 8–9: year and economics

        [TestCaseSource(typeof(PvlibReference), nameof(PvlibReference.Annual))]
        public void AnnualYield_MatchesPythonPrototype(AnnualCase c)
        {
            AnnualYieldResult result = AnnualYield.Calculate(c.Planet, c.Panel);
            Assert.AreEqual(c.EnergyWh, result.EnergyWh, c.EnergyWh * 1e-9, "energy");
            Assert.AreEqual(c.CapacityFactor, result.CapacityFactor, 1e-9, "capacity factor");
        }

        [Test]
        public void Economics_EroiAndPayback()
        {
            Assert.AreEqual(12.5, Economics.Eroi(12500.0, 1000.0), 1e-12);
            Assert.AreEqual(2.0, Economics.PaybackYears(1000.0, 500.0), 1e-12);
        }

        // Values from docs/physics/physics-verification.md ("ตาราง unit test"), issue #20

        [TestCase(0.0, 0.9997)]
        [TestCase(30.0, 1.1540)]
        [TestCase(48.19, 1.4980)]
        [TestCase(60.0, 1.9943)]
        [TestCase(70.0, 2.9031)]
        [TestCase(80.0, 5.5860)]
        [TestCase(85.0, 10.3058)]
        [TestCase(88.0, 19.4332)]
        [TestCase(90.0, 37.9196)]
        public void Report_AirMass(double zenith, double expected)
        {
            Assert.AreEqual(expected, Atmosphere.AirMassKastenYoung(zenith), 1e-4);
