        [TestCase(95.0)]
        [TestCase(120.0)]
        [TestCase(180.0)]
        public void AirMass_BelowHorizon_IsCappedNotNaN(double zenith)
        {
            double am = Atmosphere.AirMassKastenYoung(zenith);
            Assert.IsFalse(double.IsNaN(am));
            Assert.AreEqual(37.9196, am, 1e-4);
